using System.Text.RegularExpressions;
using Microsoft.Extensions.Options;
using AndalusiaAcademy.API.Services.Interfaces.Storage;

namespace AndalusiaAcademy.API.Services.Implementations.Storage;

/// <summary>
/// Stores objects as files under a private root directory. Object keys are generated by <see cref="NewObjectKey"/>
/// and strictly validated, so callers can never address paths outside the root.
/// </summary>
public sealed partial class LocalFileStorage : IFileStorage
{
    private readonly string _root;

    public LocalFileStorage(IOptions<FileStorageOptions> options, IHostEnvironment environment)
    {
        var configured = options.Value.RootPath;
        _root = Path.GetFullPath(string.IsNullOrWhiteSpace(configured)
            ? Path.Combine(environment.ContentRootPath, "App_Data", "files")
            : configured);
    }

    /// <summary>Opaque, collision-free key such as <c>2026/11/3f2a…</c>; the original file name is never part of it.</summary>
    public static string NewObjectKey(DateTimeOffset now) =>
        $"{now.UtcDateTime:yyyy}/{now.UtcDateTime:MM}/{Guid.NewGuid():N}";

    public async Task SaveAsync(string objectKey, Stream content, CancellationToken cancellationToken = default)
    {
        var path = ResolvePath(objectKey);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);

        // Write to a temp file and rename so readers never observe a partially written object.
        var temp = path + ".part";
        try
        {
            await using (var target = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, useAsync: true))
            {
                await content.CopyToAsync(target, cancellationToken);
            }

            File.Move(temp, path);
        }
        catch
        {
            TryDelete(temp);
            throw;
        }
    }

    public Task<Stream> OpenReadAsync(string objectKey, CancellationToken cancellationToken = default)
    {
        var path = ResolvePath(objectKey);
        if (!File.Exists(path))
        {
            throw new FileNotFoundException("Stored object is missing.", objectKey);
        }

        Stream stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true);
        return Task.FromResult(stream);
    }

    public Task DeleteAsync(string objectKey, CancellationToken cancellationToken = default)
    {
        TryDelete(ResolvePath(objectKey));
        return Task.CompletedTask;
    }

    private string ResolvePath(string objectKey)
    {
        if (!ObjectKeyPattern().IsMatch(objectKey))
        {
            throw new ArgumentException("Invalid object key.", nameof(objectKey));
        }

        var path = Path.GetFullPath(Path.Combine(_root, objectKey.Replace('/', Path.DirectorySeparatorChar)));
        if (!path.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.Ordinal))
        {
            throw new ArgumentException("Invalid object key.", nameof(objectKey));
        }

        return path;
    }

    private static void TryDelete(string path)
    {
        try
        {
            File.Delete(path);
        }
        catch (IOException)
        {
            // Best effort: a failed delete leaves an orphan, never a broken request.
        }
        catch (UnauthorizedAccessException)
        {
        }
    }

    [GeneratedRegex(@"^\d{4}/\d{2}/[0-9a-f]{32}$")]
    private static partial Regex ObjectKeyPattern();
}
